import app from 'flarum/forum/app';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import extractText from 'flarum/common/utils/extractText';
import uploadPhoto from '../upload';
import { t } from '../util';

/**
 * The photos of a build or a log entry in a form. Saved photos (attrs.model)
 * are reordered or removed at once; new ones wait in `queue` until the form
 * is saved, then go up one at a time (sendQueue). The first photo is the cover.
 */

export class PhotoQueue {
  constructor(max) {
    this.max = max;
    this.files = [];
  }
  add(fileList, saved) {
    // FileList is not iterable in the DOM lib this project targets (no dom.iterable).
    for (const file of Array.from(fileList)) {
      if (!/^image\//.test(file.type)) continue;
      if (saved + this.files.length >= this.max) break;
      this.files.push({
        file,
        preview: URL.createObjectURL(file)
      });
    }
    m.redraw();
  }
  remove(item) {
    URL.revokeObjectURL(item.preview);
    this.files = this.files.filter(f => f !== item);
  }

  /** Uploads every queued photo to the build or entry at `url`; calls progress(n, total). Returns the names that failed. */
  async send(url, progress) {
    const failed = [];
    const files = [...this.files];
    for (let i = 0; i < files.length; i++) {
      progress(i + 1, files.length);
      try {
        await uploadPhoto(files[i].file, url + '/photos');
        this.remove(files[i]);
      } catch (e) {
        failed.push(files[i].file.name);
      }
    }
    return failed;
  }
}
export default class PhotoManager {
  view(vnode) {
    const {
      model,
      queue,
      endpoint,
      cover = true
    } = vnode.attrs;
    const saved = model?.photos?.() || [];
    const total = saved.length + queue.files.length;
    const full = total >= queue.max;
    const tile = (src, i, actions) => m("li", {
      className: 'GaragePhotoManager-item' + (cover && i === 0 ? ' is-cover' : '')
    }, m("img", {
      src: src,
      alt: ""
    }), cover && i === 0 ? m("span", {
      className: "GaragePhotoManager-cover"
    }, t('edit.cover')) : null, m("span", {
      className: "GaragePhotoManager-tools"
    }, actions));
    return m("div", {
      className: 'GaragePhotoManager' + (this.dragging ? ' is-dragging' : ''),
      ondragover: e => {
        e.preventDefault();
        this.dragging = true;
      },
      ondragleave: () => this.dragging = false,
      ondrop: e => {
        e.preventDefault();
        this.dragging = false;
        queue.add(e.dataTransfer.files, saved.length);
      }
    }, m("ul", {
      className: "GaragePhotoManager-list"
    }, saved.map((photo, i) => tile(photo.small, i, [cover && i > 0 ? m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-star",
      "aria-label": extractText(t('edit.make_cover')),
      title: extractText(t('edit.make_cover')),
      onclick: () => this.order(endpoint, model, i, 0)
    }) : null, i > 0 ? m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-arrow-left",
      "aria-label": extractText(t('edit.move_left')),
      onclick: () => this.order(endpoint, model, i, i - 1)
    }) : null, i < saved.length - 1 ? m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-arrow-right",
      "aria-label": extractText(t('edit.move_right')),
      onclick: () => this.order(endpoint, model, i, i + 1)
    }) : null, m(Button, {
      className: "Button Button--icon",
      icon: "far fa-trash-alt",
      "aria-label": extractText(t('edit.remove_photo')),
      onclick: () => this.remove(endpoint, model, i)
    })])), queue.files.map((item, j) => tile(item.preview, saved.length + j, [m("span", {
      className: "GaragePhotoManager-pending"
    }, t('edit.pending')), m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-xmark",
      "aria-label": extractText(t('edit.remove_photo')),
      onclick: () => queue.remove(item)
    })])), !full ? m("li", {
      className: "GaragePhotoManager-add"
    }, m("label", null, m(Icon, {
      name: "fas fa-camera"
    }), m("span", null, t('edit.add_photos')), m("input", {
      type: "file",
      accept: "image/jpeg,image/png,image/webp",
      multiple: true,
      onchange: e => {
        const input = e.target;
        queue.add(input.files, saved.length);
        input.value = '';
      }
    }))) : null), m("p", {
      className: "helpText"
    }, t(cover ? 'edit.photos_help' : 'edit.entry_photos_help', {
      count: queue.max
    })));
  }
  order(endpoint, model, from, to) {
    const order = model.photos().map((_, i) => i);
    const [moved] = order.splice(from, 1);
    order.splice(to, 0, moved);
    app.request({
      method: 'POST',
      url: `${endpoint}/photos/order`,
      body: {
        order
      }
    }).then(payload => {
      app.store.pushPayload(payload);
      m.redraw();
    });
  }
  remove(endpoint, model, index) {
    if (!confirm(extractText(t('edit.remove_photo_confirm')))) return;
    app.request({
      method: 'POST',
      url: `${endpoint}/photos/remove`,
      body: {
        url: model.photos()[index].url
      }
    }).then(payload => {
      app.store.pushPayload(payload);
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-garage', 'forum/components/PhotoManager', PhotoManager);